// Request-context middleware (Phase 15).
//
// Purpose:
//  - Generate a short requestId for every request (for log
//    correlation and for the AuditLog's optional `requestId` field).
//  - Capture a sanitized version of `ip` and `userAgent` for the
//    audit context.
//
// Design notes:
//  - The requestId is generated by the SERVER, never read from a
//    client header. We do not trust `X-Request-Id` because it
//    can be spoofed; we always generate a fresh UUID.
//  - The IP is taken from `req.ip` (Express) which honors
//    `app.set('trust proxy', ...)` (Phase 13). We do not parse
//    `X-Forwarded-For` here.
//  - We do NOT log anything to stdout. This middleware only
//    attaches values to `req.context` so the audit / logging
//    layer can read them later.
//  - The middleware is idempotent and stateless — registering
//    it more than once is harmless (later mounts overwrite
//    earlier values, but we never overwrite the requestId once
//    it's set).

import { randomUUID } from 'node:crypto';

const MAX_USER_AGENT = 512;
const MAX_IP = 64;

function safeStr(value, maxLen) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (trimmed.length === 0) return null;
  return trimmed.length > maxLen ? trimmed.slice(0, maxLen) : trimmed;
}

export function requestContext(req, res, next) {
  // Always generate a server-side requestId. The audit layer
  // never trusts a client-provided value.
  if (!req.context || !req.context.requestId) {
    req.context = {
      ...(req.context || {}),
      requestId: randomUUID(),
    };
  }

  // IP — from Express (honors trust proxy).
  const ip = safeStr(req.ip, MAX_IP);
  if (ip) req.context.ip = ip;

  // User-Agent — limited length, never logged in full at this layer.
  const ua = safeStr(req.headers && req.headers['user-agent'], MAX_USER_AGENT);
  if (ua) req.context.userAgent = ua;

  // Expose requestId in the response header for debugging — this
  // does NOT contain any secret and is safe to share.
  res.setHeader('X-Request-Id', req.context.requestId);

  return next();
}
